const (
	uploadDir = "./uploads"
	dbFile    = "./images.db"
)

func main() {
	// Initialize the database
	db, err := sql.Open("sqlite3", dbFile)
	if err != nil {
		log.Fatalf("Failed to open database: %v", err)
	}
	defer db.Close()

	// Create images table if it doesn't exist
	_, err = db.Exec(`CREATE TABLE IF NOT EXISTS images (id TEXT PRIMARY KEY, path TEXT)`)
	if err != nil {
		log.Fatalf("Failed to create table: %v", err)
	}

	// Ensure the upload directory exists
	if err := os.MkdirAll(uploadDir, os.ModePerm); err != nil {
		log.Fatalf("Failed to create upload directory: %v", err)
	}

	http.HandleFunc("/upload", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
			return
		}

		file, header, err := r.FormFile("file")
		if err != nil {
			http.Error(w, fmt.Sprintf(`{"error": "Invalid input: %v"}`, err), http.StatusBadRequest)
			return
		}
		defer file.Close()

		id := uuid.New().String()
		filePath := filepath.Join(uploadDir, id+filepath.Ext(header.Filename))

		out, err := os.Create(filePath)
		if err != nil {
			http.Error(w, fmt.Sprintf(`{"error": "Internal server error: %v"}`, err), http.StatusInternalServerError)
			return
		}
		defer out.Close()

		if _, err := io.Copy(out, file); err != nil {
			http.Error(w, fmt.Sprintf(`{"error": "Internal server error: %v"}`, err), http.StatusInternalServerError)
			return
		}

		_, err = db.Exec(`INSERT INTO images (id, path) VALUES (?, ?)`, id, filePath)
		if err != nil {
			http.Error(w, fmt.Sprintf(`{"error": "Internal server error: %v"}`, err), http.StatusInternalServerError)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		fmt.Fprintf(w, `{"id": "%s"}`, id)
	})

	http.HandleFunc("/images/", func(w http.ResponseWriter, r *http.Request) {
		imageId := filepath.Base(r.URL.Path)

		var filePath string
		err := db.QueryRow(`SELECT path FROM images WHERE id = ?`, imageId).Scan(&filePath)
		if err == sql.ErrNoRows {
			http.Error(w, `{"error": "Image not found"}`, http.StatusNotFound)
			return
		} else if err != nil {
			http.Error(w, fmt.Sprintf(`{"error": "Internal server error: %v"}`, err), http.StatusInternalServerError)
			return
		}

		http.ServeFile(w, r, filePath)
	})

	log.Println("Server started at 0.0.0.0:5000")
	log.Fatal(http.ListenAndServe("0.0.0.0:5000", nil))
}
